INSERT INTO public.categories (slug, name, description, is_published, sort_order) VALUES
('game-top-ups', 'Game Top-Ups', 'In-game currency and passes for popular mobile and PC titles. Order with your player identifier and we deliver to your account.', true, 1),
('gift-cards', 'Gift Cards', 'Digital gift cards and wallet codes for storefronts and entertainment brands. Region matters, so each listing states where the code works.', true, 2),
('subscriptions', 'Subscriptions', 'Streaming and service subscriptions supplied as digital plans. Each listing states the plan length and what we need from you.', true, 3),
('software', 'Software', 'Productivity, security and developer software licences. This line is being prepared and is not open for orders yet.', false, 4),
('ai-tools', 'AI', 'AI subscriptions, credits and developer APIs. This line is being prepared and is not open for orders yet.', false, 5),
('mobile', 'Mobile', 'Recharge, data packs and eSIM products. This line is being prepared and is not open for orders yet.', false, 6),
('business', 'Business', 'Hosting, domains, cloud credits and business SaaS. This line is being prepared and is not open for orders yet.', false, 7)
INSERT INTO public.products (category_id, slug, name, brand, summary, description, platform, region, delivery_method, delivery_time, requirements, redemption_instructions, refund_eligibility, tags, status, badges, image_url, seo_title, seo_description, is_published, featured_rank) VALUES
((SELECT id FROM public.categories WHERE slug='game-top-ups'), 'free-fire-diamonds', 'Free Fire Diamonds', 'Garena', 'Diamond packs for Garena Free Fire, delivered to your player ID.', 'Free Fire diamonds are added directly to your Garena account. Choose a pack, give us your player ID, and our team confirms the order before delivery. Diamonds can be used for characters, bundles, the Elite Pass and in-game events.', 'Mobile', 'Global', 'Direct top-up to player ID', 'Confirmed after order review', '["Free Fire player ID", "In-game nickname for verification"]'::jsonb, 'No code to redeem. Diamonds appear in your account balance once the top-up is completed.', 'Reviewed before fulfilment. Once diamonds are credited the order cannot be reversed.', ARRAY['free fire','garena','diamonds','battle royale','top up'], 'available', ARRAY['Popular'], '/__l5e/assets-v1/d90e8c61-276f-4b34-ba7a-3b8fa6a862d4/free-fire.jpg', 'Free Fire Diamonds in Nepal | MTDGC', 'Buy Garena Free Fire diamonds in Nepal with delivery to your player ID. Prices in NPR, confirmed by the MTDGC team before fulfilment.', true, 2),
((SELECT id FROM public.categories WHERE slug='game-top-ups'), 'pubg-mobile-uc', 'PUBG Mobile UC', 'Krafton', 'UC packs for PUBG Mobile, credited to your player ID.', 'Unknown Cash (UC) is the in-game currency for PUBG Mobile. Send us your player ID with the pack you want and we credit the UC to that account. UC covers the Royale Pass, crates and the in-game shop.', 'Mobile', 'Global', 'Direct top-up to player ID', 'Confirmed after order review', '["PUBG Mobile player ID", "In-game nickname for verification"]'::jsonb, 'No code to redeem. UC is added to your account balance after the top-up completes.', 'Reviewed before fulfilment. Once UC is credited the order cannot be reversed.', ARRAY['pubg','uc','krafton','battlegrounds','top up'], 'available', ARRAY['Best Seller'], '/__l5e/assets-v1/735e11fe-06a1-4a2d-b3ba-e523487df5ba/pubg.jpg', 'PUBG Mobile UC in Nepal | MTDGC', 'Buy PUBG Mobile UC in Nepal with delivery to your player ID. NPR pricing and order confirmation from the MTDGC team.', true, 1),
((SELECT id FROM public.categories WHERE slug='game-top-ups'), 'mobile-legends-diamonds', 'Mobile Legends Diamonds', 'Moonton', 'Diamonds and weekly pass for Mobile Legends: Bang Bang.', 'Mobile Legends diamonds are credited to your account using your user ID and zone ID. Use them for heroes, skins, the weekly diamond pass and events.', 'Mobile', 'Global', 'Direct top-up to user ID and zone ID', 'Confirmed after order review', '["Mobile Legends user ID", "Zone ID"]'::jsonb, 'No code to redeem. Diamonds appear in your account after the top-up completes.', 'Reviewed before fulfilment. Once diamonds are credited the order cannot be reversed.', ARRAY['mobile legends','mlbb','moonton','diamonds','moba'], 'available', ARRAY[]::text[], '/__l5e/assets-v1/b9599c28-eb6a-45b9-815e-9c62f9996ab3/mobile-legends.jpg', 'Mobile Legends Diamonds in Nepal | MTDGC', 'Buy Mobile Legends diamonds and the weekly pass in Nepal. Delivered to your user ID and zone ID with NPR pricing.', true, 3),
((SELECT id FROM public.categories WHERE slug='game-top-ups'), 'clash-of-clans-passes', 'Clash of Clans Passes', 'Supercell', 'Gold Pass and event offers for Clash of Clans.', 'Clash of Clans passes and event offers are supplied through your Supercell ID. Our team confirms availability for the current season before fulfilling the order.', 'Mobile', 'Global', 'Supercell ID assisted fulfilment', 'Confirmed after order review', '["Supercell ID email", "Player tag"]'::jsonb, 'Season passes activate on your account once the purchase is completed.', 'Reviewed before fulfilment. Season passes cannot be reversed once activated.', ARRAY['clash of clans','supercell','gold pass','strategy'], 'available', ARRAY[]::text[], '/__l5e/assets-v1/edb2716b-c377-443e-94ce-b21ab7da674e/clash.jpg', 'Clash of Clans Gold Pass in Nepal | MTDGC', 'Buy the Clash of Clans Gold Pass and event offers in Nepal. NPR pricing with order confirmation from MTDGC.', true, 5),
((SELECT id FROM public.categories WHERE slug='subscriptions'), 'netflix-subscription', 'Netflix Subscription', 'Netflix', 'Netflix plans supplied for one to twelve months.', 'Netflix subscription plans supplied by the MTDGC team. Tell us the plan length you need and the email you want the subscription attached to. We confirm availability before you pay.', 'Web, mobile and smart TV', 'Nepal', 'Account based subscription', 'Confirmed after order review', '["Delivery email address", "WhatsApp number for confirmation"]'::jsonb, 'Sign in on netflix.com with the details we send you after fulfilment.', 'Reviewed before fulfilment. Partially used subscription periods are not refundable.', ARRAY['netflix','streaming','subscription','entertainment'], 'available', ARRAY['Popular'], '/__l5e/assets-v1/a082c35e-3108-4e11-9dc2-f5641ad87ded/netflix.jpg', 'Netflix Subscription in Nepal | MTDGC', 'Netflix subscription plans for Nepal from one to twelve months. NPR pricing and confirmation before payment.', true, 4),
((SELECT id FROM public.categories WHERE slug='gift-cards'), 'roblox-gift-card', 'Roblox Gift Card', 'Roblox', 'Digital Roblox gift cards for Robux and Premium.', 'Roblox digital gift cards are delivered as a redemption code. Codes are region specific, so check the region shown on the denomination you select before ordering.', 'Web and mobile', 'Global', 'Digital code sent to your delivery email', 'Confirmed after order review', '["Delivery email address"]'::jsonb, 'Redeem the code at roblox.com/redeem while signed in to the account that should receive the credit.', 'Reviewed before fulfilment. Codes that have been revealed or redeemed cannot be refunded.', ARRAY['roblox','robux','gift card','code'], 'available', ARRAY[]::text[], '/__l5e/assets-v1/f3d8c188-e860-46ab-8290-480d6fcc88f1/roblox.jpg', 'Roblox Gift Cards in Nepal | MTDGC', 'Buy digital Roblox gift cards in Nepal. Codes delivered to your email after the MTDGC team confirms your order.', true, 6),
((SELECT id FROM public.categories WHERE slug='gift-cards'), 'steam-wallet-code', 'Steam Wallet Code', 'Valve', 'Steam wallet codes for topping up your Steam balance.', 'Steam wallet codes add credit to your Steam account balance. Wallet codes are tied to a store region, so the region shown on each denomination must match your Steam account region. This listing is being prepared and is not open for orders yet.', 'PC', 'Global', 'Digital code sent to your delivery email', 'Confirmed after order review', '["Delivery email address", "Steam account region"]'::jsonb, 'Redeem the code under Games, Redeem a Steam Wallet Code in the Steam client.', 'Reviewed before fulfilment. Codes that have been revealed or redeemed cannot be refunded.', ARRAY['steam','valve','wallet','gift card','pc'], 'coming_soon', ARRAY['Coming Soon'], '/__l5e/assets-v1/a11a2dce-acdb-4ea0-a79f-f4abec8ea095/steam.jpg', 'Steam Wallet Codes in Nepal | MTDGC', 'Steam wallet codes for Nepal. This product line is being prepared by MTDGC and is not open for orders yet.', true, 7)
